type LogoProps = Omit<ComponentProps<"svg">, "children" | "viewBox"> & {
  /** Accessible name. Ignored when `decorative` is set. */
  label?: string;
  /** Hide from assistive tech, e.g. when a link around it already names it. */
  decorative?: boolean;
};

export function Logo({
  label = "NortBrand",
  decorative = false,
  className,
  ...props
}: LogoProps) {
  return (
    <svg
      viewBox={VIEW_BOX}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={cn("h-auto w-26 shrink-0", className)}
      {...(decorative
        ? { "aria-hidden": true }
        : { role: "img", "aria-label": label })}
      focusable="false"
      {...props}
    >
      <path
        d={MARK}
        className="stroke-action-primary"
        strokeWidth={4.4}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path d={WORDMARK} fill="currentColor" />
    </svg>
  );
}

/*
 * The squiggle mark on its own (Figma Contact "Brand Squiggle" 283:39): decorative,
 * always brand red. The view box crops the logo's view box to the mark.
 */
const MARK_VIEW_BOX = "68.36 141.12 45.5 43.24";

export function LogoMark({ className }: { className?: string }) {
  return (
    <svg
      viewBox={MARK_VIEW_BOX}
      fill="none"
      aria-hidden
      focusable="false"
      className={cn("shrink-0", className)}
    >
      <path
        d={MARK}
        className="stroke-action-primary"
        strokeWidth={4.4}
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}
